st.header(
    "1. Image Upload"
)

uploaded_file = st.file_uploader(
    "Upload a skin lesion image",
    type=[
        "jpg",
        "jpeg",
        "png",
        "bmp",
        "tif",
        "tiff"
    ],
    key="main_image"
)


# ============================================================
# NO IMAGE
# ============================================================

if uploaded_file is None:

    st.info(
        "Please upload a skin lesion image to begin the analysis."
    )

    st.stop()


# ============================================================
# LOAD IMAGE
# ============================================================

try:

    image = Image.fromarray(
        load_image(
            uploaded_file
        )
    )

except Exception as e:

    st.error(
        f"Unable to read the image: {e}"
    )

    st.stop()


# ============================================================
# IMAGE ARRAYS
# ============================================================

image_rgb = np.array(
    image
)

image_bgr = cv2.cvtColor(
    image_rgb,
    cv2.COLOR_RGB2BGR
)


# ============================================================
# IMAGE INFORMATION
# ============================================================

st.subheader(
    "Uploaded Image"
)

col1, col2 = st.columns(
    [2, 1]
)

with col1:

    st.image(
        image,
        caption="Original Image",
        use_container_width=True
    )

with col2:

    st.markdown(
        "### Image Information"
    )

    st.write(
        f"**Filename:** {uploaded_file.name}"
    )

    st.write(
        f"**Width:** {image.width} pixels"
    )

    st.write(
        f"**Height:** {image.height} pixels"
    )

    st.write(
        f"**Color mode:** {image.mode}"
    )


# ============================================================
# SECTION 2
# ABCD ANALYSIS
# ============================================================

st.header(
    "2. ABCD Analysis"
)

with st.expander(
    "ABCD Analysis",
    expanded=False
):

    try:

        abcd_results, lesion_mask = (
            analyze_abcd(
                image_rgb,
                pixel_size=pixel_size_mm
            )
        )

        col1, col2, col3, col4 = st.columns(
            4
        )

        with col1:

            st.metric(
                "Asymmetry",
                f"{abcd_results['Asymmetry Index']:.3f}"
            )

        with col2:

            st.metric(
                "Circularity",
                f"{abcd_results['Circularity']:.3f}"
            )

        with col3:

            st.metric(
                "Color Variation",
                f"{abcd_results['Color Variation']:.2f}"
            )

        with col4:

            st.metric(
                "Diameter",
                f"{abcd_results['Diameter (mm)']:.2f} mm"
            )

        st.markdown(
            "### ABCD Score"
        )

        st.metric(
            "Score",
            f"{abcd_results['ABCD Score']} / "
            f"{abcd_results['Maximum Score']}"
        )

        mask_display = (
            lesion_mask > 0
        ).astype(
            np.uint8
        ) * 255

        st.image(
            mask_display,
            caption="Estimated Lesion Mask",
            use_container_width=True
        )

        st.caption(
            """
            Diameter uses the sidebar pixel-size setting. Use a calibrated
            scale for research measurements; uncalibrated estimates may not
            represent physical lesion size.
            """
        )

    except Exception as e:

        st.error(
            f"ABCD analysis failed: {e}"
        )




# ============================================================
# SECTION 3
# IMAGE PROCESSING
# ============================================================

st.header(
    "3. Image Processing"
)

